const EMO_RE=/(\p{Extended_Pictographic}|[➕➤✕✖ℹ✔✏✉⚙⚠♿\uE000-\uF8FF])[\u{1F3FB}-\u{1F3FF}]?\uFE0F?(\u200D\p{Extended_Pictographic}[\u{1F3FB}-\u{1F3FF}]?\uFE0F?)*/gu;
function emoIcon(m){const k=m.replace(/[\uFE0F\u{1F3FB}-\u{1F3FF}]/gu,'');const v=EMO_IC[k]||EMO_IC[String.fromCodePoint(k.codePointAt(0))];if(!v)return null;const [n,c]=v.split(':');return ICONS2[n]?{n,c:c||''}:null;}
/* אייקון כמחרוזת SVG עצמאית (להדפסה ולרקע) */
function ic2svg(n,size,color){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="'+(size||20)+'" height="'+(size||20)+'" fill="none" stroke="'+(color||'currentColor')+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="vertical-align:-.2em'+(color?';color:'+color:'')+'">'+(ICONS2[n]||'')+'</svg>';}
/* טקסט עם אימוג'י ← HTML עם אייקונים (הטקסט עצמו מוצפן) */
function emoToSvg(t,size,color){t=String(t==null?'':t);let out='',last=0;EMO_RE.lastIndex=0;for(const m of t.matchAll(EMO_RE)){const i=emoIcon(m[0]);if(!i)continue;out+=esc2(t.slice(last,m.index))+ic2svg(i.n,size,i.c||color);last=m.index+m[0].length;}return out+esc2(t.slice(last));}
